example.code:
// Simple hash with default 32-byte output
using var hasher = new KangarooTwelve();
hasher.Update(Encoding.UTF8.GetBytes("Hello, World!"));
byte[] hash = hasher.Finalize();

// With customization string
using var hasher2 = new KangarooTwelve(customization: Encoding.UTF8.GetBytes("MyApp"));
hasher2.Update(data);
byte[] hash2 = hasher2.Finalize();

// Custom output length (64 bytes)
using var hasher3 = new KangarooTwelve(outputLength: 64);
hasher3.Update(data);
byte[] hash3 = hasher3.Finalize();

using var hasher = new MetroHash128();
hasher.Update(Encoding.UTF8.GetBytes("Hello, World!"));
UInt128 hash = hasher.Finalize();

// Or use the static method
UInt128 hash = MetroHash128.Hash(data);

using var hasher = new MetroHash64();
hasher.Update(Encoding.UTF8.GetBytes("Hello, World!"));
ulong hash = hasher.Finalize();

// Or use the static method
ulong hash = MetroHash64.Hash(data);

// Basic usage
using var hasher = new MurmurHash3_32();
hasher.Update(Encoding.UTF8.GetBytes("Hello, World!"));
uint hash = hasher.Finalize();

// With custom seed
using var seededHasher = new MurmurHash3_32(seed: 0xdeadbeef);
seededHasher.Update(data);
uint seededHash = seededHasher.Finalize();

// Stream processing
using var streamHasher = new MurmurHash3_32();
using var file = File.OpenRead("largefile.bin");
byte[] buffer = new byte[8192];
int read;
while ((read = file.Read(buffer)) > 0) {
    streamHasher.Update(buffer.AsSpan(0, read));
}
uint fileHash = streamHasher.Finalize();

// Create a 128-bit key
ReadOnlySpan<byte> key = stackalloc byte[16] {
    0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07,
    0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e, 0x0f
};

using var hasher = new SipHash24(key);
hasher.Update(Encoding.UTF8.GetBytes("Hello, World!"));
ulong hash = hasher.Finalize();

para.code:
public class MyHash : StreamingHashBase<uint>
{
    public override int BlockSize => 4;
    public override int DigestSize => 4;

    private uint _state;

    protected override void ProcessBlock(ReadOnlySpan<byte> block) {
        // Process one complete block
        _state ^= BinaryPrimitives.ReadUInt32LittleEndian(block);
    }

    protected override uint ComputeFinal(ReadOnlySpan<byte> remaining) {
        // Handle remaining bytes and return final hash
        return _state ^ (uint)TotalBytesProcessed;
    }

    protected override void ResetCore() {
        _state = 0;
    }
}
